--
-- Table structure for table `mapping_log`
--

DROP TABLE IF EXISTS `mapping_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `mapping_log` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `pr_po_data_id` bigint NOT NULL,
  `method` enum('ITEM_MAPPING_RULE','FUZZY_MATCH','MANUAL') COLLATE utf8mb4_unicode_ci NOT NULL,
  `planning_detail_hasil_id` bigint DEFAULT NULL,
  `confidence_score` decimal(5,4) DEFAULT NULL,
  `rank_no` int DEFAULT NULL,
  `is_selected` tinyint(1) DEFAULT NULL,
  `processing_time` decimal(10,4) DEFAULT NULL,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `pr_po_data_id` (`pr_po_data_id`),
  KEY `planning_detail_hasil_id` (`planning_detail_hasil_id`),
  CONSTRAINT `mapping_log_ibfk_1` FOREIGN KEY (`pr_po_data_id`) REFERENCES `pr_po_data` (`id`) ON DELETE CASCADE,
  CONSTRAINT `mapping_log_ibfk_2` FOREIGN KEY (`planning_detail_hasil_id`) REFERENCES `planning_detail` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=13606 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
