--
-- Table structure for table `planning_detail`
--

DROP TABLE IF EXISTS `planning_detail`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `planning_detail` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `planning_header_id` bigint NOT NULL,
  `kategori_id` bigint DEFAULT NULL,
  `month` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Bulan planning, contoh: Jan, Feb, Mar',
  `item` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `planning_amount` decimal(18,2) NOT NULL,
  `remarks` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status_realisasi` enum('OPEN','PROSES','CLOSED','CANCELLED') COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Agregat status realisasi dari semua PR yang di-mapping ke item ini',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `planning_header_id` (`planning_header_id`),
  KEY `kategori_id` (`kategori_id`),
  CONSTRAINT `planning_detail_ibfk_1` FOREIGN KEY (`planning_header_id`) REFERENCES `planning_header` (`id`),
  CONSTRAINT `planning_detail_ibfk_2` FOREIGN KEY (`kategori_id`) REFERENCES `kategori` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=254 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

